/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('promotions')` (or `ctx.tryUse` for an optional dependency). */
export interface PromotionsPublicApi {
  /** Link targets for ad destination pickers (search by q, or resolve ids): platform promotion campaigns that are live or scheduled (/deals?campaign={id}); resolving ids also returns ended ones as unavailable, each with its store path the app opens, a label, a short meta line, an image and whether it is shown in the store. Unknown ids are left out. Used by: advertising. */
  linkTargets(input: { kind: 'deal', q?: string, ids?: string[], limit?: number }): Promise<common.LinkTarget[]>;
  /** Current markdown or flash price, was price, badges, purchase limit and countdown per offer. Used for product cards, the purchase box and cart lines so prices match everywhere (plan ch. 15: consistent across product page, cart, checkout and confirmation). Used by: offers, search, cart, content, wishlist, graphql, reports. */
  priceOffers(offerIds: string[], ctx: { customerId?: string, at?: string }): Promise<OfferPromotion[]>;
  /** Runs eligibility, stacking, limits and budgets for a cart or checkout quote. Returns per-line discounts with the funding split, free-shipping packages, applied codes with the items they cover and rejected codes with a reason the customer can read. Pure read: nothing is reserved. Used by: cart, checkout. */
  evaluateCart(input: CartEvaluationInput): Promise<CartEvaluation>;
  /** Holds budget, usage counts and flash deal stock for a quote while payment runs. Fails with BUDGET_EXHAUSTED, USAGE_LIMIT_REACHED (total, per-customer or code limit, details.limit) or DEAL_SOLD_OUT so checkout can show the revised total before the customer commits (plan ch. 6); also PURCHASE_LIMIT_EXCEEDED (per-customer unit limit of a markdown or flash price, details.limit), COUPON_NOT_ELIGIBLE (details.reason expired: a campaign of the quote is no longer running), CONFLICT (the quote's validUntil has passed: evaluate again), NOT_FOUND (unknown evaluationId) and VALIDATION_FAILED (no idempotency key). Same evaluation and key while the hold is live: the same reservation. Used by: checkout. */
  reserveRedemption(evaluationId: string, idempotencyKey: string): Promise<RedemptionReservation>;
  /** Binds a reservation to the placed order (line id → order item id). Also triggered by orders.order.placed. Used by: checkout. */
  commitRedemption(reservationId: string, orderId: string, orderItemIds: Record<string, string>): Promise<Redemption[]>;
  /** Releases held budget, usage and deal stock when payment fails or the quote expires. Used by: checkout. */
  releaseRedemption(reservationId: string): Promise<void>;
  /** Discount allocations of one order item with platform and seller parts. Finance charges commission on the price after the seller-funded part only and credits the platform-funded part to seller proceeds. Used by: finance, orders, returns, graphql. */
  fundingSplitFor(orderItemId: string): Promise<FundingSplit>;
  /** Coupon share to deduct when refunding part of an order (coupons are split across items by value). Used to cap refunds at the remaining refundable amount. Used by: returns, payments, support. */
  refundShare(orderItemId: string, quantity: number): Promise<RefundShare>;
  /** Name, period, terms and status for campaign pages, banners and ads. Used by: content, advertising, graphql. */
  getPublicCampaign(campaignId: string): Promise<PublicCampaign | null>;
  /** False when ended, paused, out of budget or sold out. Advertising stops linked ads; content hides teasers. Used by: advertising, content. */
  isCampaignActive(campaignId: string): Promise<{ active: boolean, reason?: string }>;
  /** Flash deals for the homepage Deals section. campaignId limits the result to one campaign (content SourceRule.campaignId: a section or collection fed by one promotion). Used by: content, graphql. */
  liveDeals(opts: { limit: number, campaignId?: string }): Promise<FlashSaleBlock[]>;
  /** Honest 'was' price: delegates to offers.lowestPrice(offerId, offers.wasPriceLookbackDays (read with ctx.settings.read; offers owns the window, decision O5), campaignStart or now) and returns null when offers has no history for the window. No price history is kept in promotions. Used by: offers, wishlist. */
  referencePrice(offerId: string): Promise<common.Money | null>;
  /** Deals page data in one call: tab counts, live flash sales, clippable coupons (clipped state for the customer), the first clearance batch, upcoming events with reminder state, the combination rules and serverTime for countdowns. Same data as GET /api/store/promotions/deals. Used by: graphql, workqueues. */
  getDealsPage(ctx: { customerId?: string, at?: string }): Promise<DealsPage>;
  /** Clearance products page by page (GET /deals/clearance). Used by: graphql. */
  listClearance(paging: common.PageInput): Promise<common.Page<DealProduct>>;
  /** One flash sale with live claimed meters, deal stock and countdown (GET /flash-sales/{campaignId}). Used by: graphql. */
  getFlashSale(campaignId: string): Promise<FlashSaleBlock | null>;
  /** Clippable coupons that cover each product, with the customer's clipped state (the coupons part of GET /products/{productId}). Batched per request. Used by: graphql. */
  couponsForProduct(productIds: string[], ctx: { customerId?: string }): Promise<Record<string, CouponCard[]>>;
  /** Give one customer their own single-use code of a coupon campaign (a Daily rewards redemption, 2026-10-22). The campaign must be a coupon campaign that is scheduled or running (CAMPAIGN_NOT_ACTIVE otherwise); the code is unique, max_redemptions 1, assigned to the customer, and shows in their coupons. The same key returns the same code. Used by: rewards, departments. */
  issueCode(campaignId: string, customerId: string, idempotencyKey: string): Promise<IssuedCoupon>;
  /** My coupons: available and clipped, used and expired, with the rules line (GET /coupons). Used by: graphql. */
  couponsForCustomer(customerId: string): Promise<AccountCoupons>;
  /** Live seller-funded promotions for the storefront (automatic or by code), soonest ending first. Same eligibility and period rules as priceOffers; platform campaigns are not included. Used by: sellers, graphql. */
  activeSellerPromotions(sellerIds: string[], ctx: { customerId?: string, at?: string }): Promise<Record<string, PromoBanner[]>>;
  /** Export rows for reports dataset promotions.admin.campaigns (campaign results) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`promotions.<table>`, ctx.mongo.table(name)). */
export interface PromotionsDb {
  /** Platform campaigns and seller discounts (owner_kind). Seller discounts are seller-funded and skip Finance confirmation. */
  campaigns: {
    id: string;
    ref: string;
    name: string;
    description: string | null;
    internal_note: string | null;
    owner_kind: 'platform' | 'seller';
    seller_id: string | null;
    kind: string;
    discount: Json;
    auto_apply: boolean;
    starts_at: Date;
    ends_at: Date;
    time_zone: string;
    scope_mode: string;
    eligibility: Json;
    budget_amount: number | null;
    budget_used: number;
    usage_cap: number | null;
    usage_count: number;
    per_customer: number | null;
    per_order: number | null;
    per_customer_units: number | null;
    funding_owner: string;
    platform_share_bps: number | null;
    cost_center: string | null;
    /** Funding.note */
    funding_note: string | null;
    stacking: Json;
    exclusive_group: string | null;
    participation: Json | null;
    /** DealsPlacement */
    deals: Json | null;
    terms: string | null;
    status: string;
    ended_reason: string | null;
    approval_request_id: string | null;
    currency: string;
    created_by: string;
    created_at: Date;
    updated_at: Date;
    version: number;
  };
  /** Included and excluded categories, products, offers, sellers, brands */
  campaign_targets: {
    campaign_id: string;
    kind: string;
    target_id: string;
    excluded: boolean;
    label: string | null;
  };
  /** Resolved offer set per campaign (rebuilt on scope change and offer events) for fast evaluation and the eligible count */
  eligible_offers: {
    campaign_id: string;
    offer_id: string;
    seller_id: string;
    official_store: boolean;
    eligible: boolean;
    reason: string | null;
    refreshed_at: Date;
  };
  /** Finance confirmation per submission */
  funding_reviews: {
    id: string;
    campaign_id: string;
    state: string;
    sent_at: Date;
    reviewer_id: string | null;
    decided_at: Date | null;
    checks: Json;
    platform_max: number;
    sellers_max: number;
    expected_sales: number | null;
    margin_impact_pts: string | null;
    comment: string | null;
    approval_request_id: string | null;
  };
  /** Seller invitations and consent for platform campaigns */
  participations: {
    id: string;
    campaign_id: string;
    seller_id: string;
    state: string;
    seller_share_bps: number;
    platform_share_bps: number;
    respond_by: Date | null;
    consented_at: Date | null;
    consented_by: string | null;
    consent_text: string | null;
    reason: string | null;
    updated_at: Date;
  };
  participation_offers: {
    participation_id: string;
    offer_id: string;
    eligible: boolean;
    ineligible_reasons: Json;
    included: boolean;
  };
  /** Deal price, deal stock and purchase limit per offer in a flash sale. approved_* keep what Finance confirmed (set at confirmFunding): a live or paused sale can only change within them */
  flash_items: {
    id: string;
    campaign_id: string;
    offer_id: string;
    deal_price: number;
    regular_price: number;
    deal_stock: number;
    claimed: number;
    reserved: number;
    purchase_limit: number;
    state: string;
    sold_out_at: Date | null;
    approved_deal_price: number | null;
    approved_deal_stock: number | null;
    approved_purchase_limit: number | null;
  };
  coupon_codes: {
    id: string;
    campaign_id: string;
    /** unique by code among active codes, compared without case; a code frees up when its campaign ends or is cancelled */
    code: string;
    kind: 'shared' | 'unique';
    max_redemptions: number | null;
    redemptions: number;
    assigned_customer_id: string | null;
    /** issueCode idempotency key */
    issue_key: string | null;
    active: boolean;
    created_at: Date;
  };
  /** Coupons a customer clipped; applied automatically at checkout */
  coupon_clips: {
    customer_id: string;
    campaign_id: string;
    code_id: string | null;
    clipped_at: Date;
  };
  /** Short-lived cart evaluations referenced by reservations */
  evaluations: {
    id: string;
    input_hash: string;
    result: Json;
    valid_until: Date;
  };
  /** Reserved then committed discounts per order */
  redemptions: {
    id: string;
    campaign_id: string;
    code_id: string | null;
    reservation_id: string;
    idempotency_key: string;
    evaluation_id: string;
    order_id: string | null;
    customer_id: string | null;
    guest_key: string | null;
    state: string;
    amount: number;
    platform_part: number;
    seller_part: number;
    reversed: number;
    currency: string;
    expires_at: Date | null;
    created_at: Date;
  };
  /** Per order item allocation; the source for fundingSplitFor and refundShare */
  redemption_lines: {
    redemption_id: string;
    line_id: string;
    order_item_id: string | null;
    offer_id: string;
    seller_id: string;
    quantity: number;
    amount: number;
    platform_part: number;
    seller_part: number;
    reversed: number;
  };
  /** Per-customer uses and units for limits (row-locked during reservation) */
  usage_counters: {
    campaign_id: string;
    /** customer id or guest email hash */
    customer_key: string;
    uses: number;
    units: number;
  };
  /** Remind me on upcoming Deals events */
  event_reminders: {
    customer_id: string;
    campaign_id: string;
    created_at: Date;
    sent_at: Date | null;
  };
  /** Every submission, decision, status change, edit and removal with reason */
  campaign_log: {
    id: string;
    campaign_id: string;
    action: string;
    reason: string | null;
    detail: Json | null;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
  /** Read model rolled up from order, redemption and return events */
  campaign_results_daily: {
    campaign_id: string;
    day: string;
    sales: number;
    orders: number;
    cost_platform: number;
    cost_seller: number;
    redemptions: number;
    returned_items: number;
    official_cost_basis: number;
    official_revenue: number;
  };
}

